body:
package {
    default_team: "trendy_team_aaos_framework",
    default_applicable_licenses: ["Android-Apache-2.0"],
}

filegroup {
    name: "car-frameworks-updatable-service-sources",
    srcs: [
        "src/**/*.java",
    ],
    visibility: [
        ":__subpackages__",
    ],
}

java_library {
    name: "car-frameworks-service-module",
    installable: true,
    libs: [
            "android.car",
            "android.car.builtin.stubs.module_lib",
            "car-frameworks-service.stubs.module_lib",
            "framework-annotations-lib",
            "framework-permission-s.stubs.module_lib"
    ],
    srcs: [
        ":car-frameworks-updatable-service-sources",
    ],

    sdk_version: "module_current",
    // TODO(b/288271411): enable it when car mainline module is supported
    // min_sdk_version: "33",
    apex_available: [
        "//apex_available:platform",
        "com.android.car.framework"
    ],
}

package {
    default_team: "trendy_team_aaos_framework",
    default_applicable_licenses: ["Android-Apache-2.0"],
}

java_sdk_library {
    name: "car-frameworks-service",
    libs: [
        "services",
        "android.car",
        "android.car.builtin.stubs.module_lib", // Will remove once split is complete
        "android.hardware.automotive.vehicle-V2.0-java",
    ],
    srcs: [
        "src/**/*.java",
    ],
    static_libs: [
        "android.car.watchdoglib",
        "android.automotive.watchdog.internal-java",
        "car-builtin-protos",
    ],
    api_lint: {
        enabled: true,
    },

    stub_only_libs: [
        "framework-annotations-lib",
    ],

    droiddoc_options: [
        "--include-annotations --pass-through-annotation android.annotation.RequiresApi",
    ],

    apex_available: [
        "//apex_available:platform",
        "com.android.car.framework",
    ],

    unsafe_ignore_missing_latest_api: true,

    test: {
        enabled: false,
    },
    system: {
        enabled: true,
        sdk_version: "module_current",
    },
    module_lib: {
        enabled: true,
        sdk_version: "module_current",
    },
}
